from taf.internal.managedobject import ManagedObject
import logging

logger = logging.getLogger(__name__)


class AirPhoneUeSim(ManagedObject):
    """ AirPhoneUeSim
    Methods:
    - :meth:`attach`: executes the attach process
    - :meth:`detach`: executes the detach process
    """

    def __init__(self, egate_console, *args, **kwargs):
        super(AirPhoneUeSim, self).__init__(**kwargs)
        self.add_prerequisite(egate_console)
        self._egate_console = egate_console

    def attach(self, id, phy_cell_id=0, arfcn=0, brs_port0=0,
               initial_beam_index=0):
        cmd = self._generate_attach_cmd(id=id, phy_cell_id=phy_cell_id,
                                        arfcn=arfcn, brs_port0=brs_port0,
                                        initial_beam_index=initial_beam_index)
        return self._egate_console.execute(cmd)

    @staticmethod
    def _generate_command(template, arglist, kwargs):
        cmd = template.strip()
        for argname in arglist:
            argvalue = kwargs[argname]
            if argvalue is not None:
                cmd = cmd + " {}={}".format(argname, argvalue)
        return cmd

    @staticmethod
    def _generate_attach_cmd(**cmd_args):
        cmd_template = ('ue_attach id={id} phy_cell_id={phy_cell_id} '
                        'arfcn={arfcn} brs_port0={brs_port0} '
                        'initial_beam_index={initial_beam_index}')
        return cmd_template.format(**cmd_args)

    def detach(self, id):
        detach_cmd = self._generate_detach_cmd(id=id)
        return self._egate_console.execute(detach_cmd)

    @staticmethod
    def _generate_detach_cmd(**cmd_args):
        cmd_template = 'ue_detach id={id}'
        return cmd_template.format(**cmd_args)

    def configure(self, file):
        configure_cmd = self._generate_configure_cmd(file=file)
        return self._egate_console.execute(configure_cmd)

    @staticmethod
    def _generate_configure_cmd(**cmd_args):
        cmd_template = 'cfg file={file}'
        return cmd_template.format(**cmd_args)

    def ul_traffic_start(self, trf_data_ue, trf_data_id, dir, trf_id=None, mbps=None,
                         size=None, period_ms=None, burst=None, protocol=None, remote_ip=None):
        ts_cmd = self._generate_ul_traffic_start_cmd(self, trf_data_ue, trf_data_id, mbps, dir, trf_id,
                                                     size, period_ms, burst,
                                                     protocol, remote_ip)
        return self._egate_console.execute(ts_cmd)

    def _generate_ul_traffic_start_cmd(self, *args):
        arg_names = ['ue', 'id', 'mbps', 'dir', 'trf_id', 'size',
                     'period_ms', 'burst', 'protocol', 'remote_ip']
        arg_values = [args][0][1:]
        cmd_template = 'trf_data_start'
        for i, name in enumerate(arg_names):
            if arg_values[i]:
                cmd_template += ' {}={}'.format(name, arg_values[i])
        return cmd_template

    def ul_traffic_stop(self, trf_data_ue=1, trf_data_id=1, dir='ul', trf_id=1):
        ts_cmd = self._generate_ul_traffic_stop_cmd(trf_data_ue=trf_data_ue,
                                                    trf_data_id=trf_data_id,
                                                    dir=dir, trf_id=trf_id)
        return self._egate_console.execute(ts_cmd)

    @staticmethod
    def _generate_ul_traffic_stop_cmd(**cmd_args):
        cmd_template = ('trf_data_stop {trf_data_ue} {trf_data_id} {dir} '
                        '{trf_id}')
        return cmd_template.format(**cmd_args)

    def read_egate_output(self):
        return self._egate_console.read_output()

    def read_egate_output_until(self, expected, timeout=None):
        return self._egate_console.read_output_until(expected, timeout=timeout)

    def read_egate_output_until_prompt(self, timeout=None):
        ec = self._egate_console
        return ec.read_until_prompt(timeout=timeout)

